                        for _ in range(count):
                            results.append((rel, tok.start[0]))
        except (tokenize.TokenError, IndentationError, SyntaxError):
            pass

results.sort(key=lambda x: (x[0], x[1]))
with open('todos.txt', 'w', encoding='utf-8', newline='\n') as f:
